values (
  'en-bts-trivia',
  'BTS Trivia: Debut, Albums and Records',
  'From 2 Cool 4 Skool to Dynamite: eight questions on the debut, the seven members and the records that made BTS the biggest group on the planet.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"In which year did BTS officially debut?","options":[{"id":"a","text":"2010","is_correct":false},{"id":"b","text":"2013","is_correct":true},{"id":"c","text":"2016","is_correct":false},{"id":"d","text":"2019","is_correct":false}],"explanation":"BTS debuted on 13 June 2013 under Big Hit Entertainment with the single album 2 Cool 4 Skool."},{"id":"q2","question":"How many members does BTS have?","options":[{"id":"a","text":"Five","is_correct":false},{"id":"b","text":"Six","is_correct":false},{"id":"c","text":"Nine","is_correct":false},{"id":"d","text":"Seven","is_correct":true}],"explanation":"Seven: RM, Jin, Suga, J-Hope, Jimin, V and Jungkook."},{"id":"q3","question":"Who is the leader of BTS?","options":[{"id":"a","text":"Jin","is_correct":false},{"id":"b","text":"RM","is_correct":true},{"id":"c","text":"Suga","is_correct":false},{"id":"d","text":"Jungkook","is_correct":false}],"explanation":"RM (Kim Namjoon) is the leader and lead rapper — and the member who usually handled the English interviews."},{"id":"q4","question":"What is the name of BTS''s fandom?","options":[{"id":"a","text":"BLINK","is_correct":false},{"id":"b","text":"ONCE","is_correct":false},{"id":"c","text":"ARMY","is_correct":true},{"id":"d","text":"MOA","is_correct":false}],"explanation":"ARMY stands for Adorable Representative M.C. for Youth; BLINK belongs to BLACKPINK and ONCE to TWICE."},{"id":"q5","question":"Which 2020 single was BTS''s first song recorded entirely in English?","options":[{"id":"a","text":"Butter","is_correct":false},{"id":"b","text":"Permission to Dance","is_correct":false},{"id":"c","text":"Boy With Luv","is_correct":false},{"id":"d","text":"Dynamite","is_correct":true}],"explanation":"Dynamite (August 2020) was their first all-English single and their first Billboard Hot 100 number one."},{"id":"q6","question":"Which 2021 single did BTS record with Coldplay?","options":[{"id":"a","text":"My Universe","is_correct":true},{"id":"b","text":"Higher Power","is_correct":false},{"id":"c","text":"Fix You","is_correct":false},{"id":"d","text":"A Sky Full of Stars","is_correct":false}],"explanation":"My Universe came out in September 2021 as part of Coldplay''s Music of the Spheres."},{"id":"q7","question":"Which album made BTS the first K-pop act to top the Billboard 200?","options":[{"id":"a","text":"Wings","is_correct":false},{"id":"b","text":"Map of the Soul: 7","is_correct":false},{"id":"c","text":"Love Yourself: Tear","is_correct":true},{"id":"d","text":"Be","is_correct":false}],"explanation":"Love Yourself: Tear debuted at number one in May 2018 — a first for a Korean act on the album chart."},{"id":"q8","question":"Which label formed BTS?","options":[{"id":"a","text":"SM Entertainment","is_correct":false},{"id":"b","text":"YG Entertainment","is_correct":false},{"id":"c","text":"JYP Entertainment","is_correct":false},{"id":"d","text":"Big Hit Entertainment","is_correct":true}],"explanation":"Big Hit (today part of HYBE) put the group together; the other three are the classic ''big three'' K-pop agencies."}]'::jsonb,
  null,
  array['bts', 'k-pop', 'music', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
