values (
  'en-blackpink-trivia',
  'BLACKPINK Trivia: Members, Hits and Tours',
  'Jisoo, Jennie, Rosé and Lisa: eight questions on the debut, the hits and the records of the K-pop quartet that took over the world.',
  'trivia',
