  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"In which year did BLACKPINK debut?","options":[{"id":"a","text":"2014","is_correct":false},{"id":"b","text":"2016","is_correct":true},{"id":"c","text":"2018","is_correct":false},{"id":"d","text":"2020","is_correct":false}],"explanation":"They debuted on 8 August 2016 with the single album Square One and the songs Whistle and Boombayah."},{"id":"q2","question":"Which agency formed BLACKPINK?","options":[{"id":"a","text":"JYP Entertainment","is_correct":false},{"id":"b","text":"SM Entertainment","is_correct":false},{"id":"c","text":"YG Entertainment","is_correct":true},{"id":"d","text":"HYBE","is_correct":false}],"explanation":"YG Entertainment — the house of BIGBANG and 2NE1 — trained the four members for years before their debut."},{"id":"q3","question":"How many members does BLACKPINK have?","options":[{"id":"a","text":"Four","is_correct":true},{"id":"b","text":"Five","is_correct":false},{"id":"c","text":"Six","is_correct":false},{"id":"d","text":"Seven","is_correct":false}],"explanation":"Four: Jisoo, Jennie, Rosé and Lisa — no more, no less."},{"id":"q4","question":"Which member was born in Thailand?","options":[{"id":"a","text":"Jisoo","is_correct":false},{"id":"b","text":"Rosé","is_correct":false},{"id":"c","text":"Jennie","is_correct":false},{"id":"d","text":"Lisa","is_correct":true}],"explanation":"Lalisa Manobal — Lisa — was born in Buriram and raised in Bangkok, Thailand."},{"id":"q5","question":"What is the name of BLACKPINK''s fandom?","options":[{"id":"a","text":"ARMY","is_correct":false},{"id":"b","text":"MIDZY","is_correct":false},{"id":"c","text":"BLINK","is_correct":true},{"id":"d","text":"ONCE","is_correct":false}],"explanation":"BLINK blends the beginning and the end of BLACKPINK; ONCE is TWICE''s fandom."},{"id":"q6","question":"Which pop star joins BLACKPINK on the 2020 single Ice Cream?","options":[{"id":"a","text":"Ariana Grande","is_correct":false},{"id":"b","text":"Selena Gomez","is_correct":true},{"id":"c","text":"Billie Eilish","is_correct":false},{"id":"d","text":"Doja Cat","is_correct":false}],"explanation":"Ice Cream, with Selena Gomez, was the second single from The Album in August 2020."},{"id":"q7","question":"In 2023 BLACKPINK became the first K-pop act to headline which festival?","options":[{"id":"a","text":"Glastonbury","is_correct":false},{"id":"b","text":"Lollapalooza","is_correct":false},{"id":"c","text":"Primavera Sound","is_correct":false},{"id":"d","text":"Coachella","is_correct":true}],"explanation":"They headlined Coachella in April 2023, four years after becoming the first K-pop girl group to play the festival."},{"id":"q8","question":"What was BLACKPINK''s first full-length studio album?","options":[{"id":"a","text":"Square One","is_correct":false},{"id":"b","text":"The Album","is_correct":true},{"id":"c","text":"Kill This Love","is_correct":false},{"id":"d","text":"Born Pink","is_correct":false}],"explanation":"Square One was the 2016 debut single album and Kill This Love an EP; The Album (2020) was the first LP, followed by Born Pink (2022)."}]'::jsonb,
  null,
  array['blackpink', 'k-pop', 'music', 'trivia']::text[],
