values (
  'en-j-balvin-trivia',
  'J Balvin Trivia: Hits, Albums and Records',
  'From Medellín to headlining Lollapalooza: eight questions on the Colombian reggaetonero who took Latin urbano global.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"What is J Balvin''s real name?","options":[{"id":"a","text":"José Álvaro Osorio Balvín","is_correct":true},{"id":"b","text":"Juan Carlos Balvín Osorio","is_correct":false},{"id":"c","text":"Álvaro José Londoño","is_correct":false},{"id":"d","text":"José Miguel Balvin Arias","is_correct":false}],"explanation":"He was born José Álvaro Osorio Balvín in Medellín in 1985 — ''J Balvin'' is the stage name built from it."},{"id":"q2","question":"Which Colombian city is J Balvin from?","options":[{"id":"a","text":"Bogotá","is_correct":false},{"id":"b","text":"Cali","is_correct":false},{"id":"c","text":"Medellín","is_correct":true},{"id":"d","text":"Barranquilla","is_correct":false}],"explanation":"Medellín — he calls himself the city''s ''global ambassador'' and named an album after its José María Córdova airport code, Jose."},{"id":"q3","question":"Which 2017 single with Willy William became his global anthem?","options":[{"id":"a","text":"Ginza","is_correct":false},{"id":"b","text":"Safari","is_correct":false},{"id":"c","text":"X (Equis)","is_correct":false},{"id":"d","text":"Mi Gente","is_correct":true}],"explanation":"Mi Gente topped charts worldwide and earned a remix with Beyoncé."},{"id":"q4","question":"In 2019 J Balvin became the first Latin artist to headline which US festival?","options":[{"id":"a","text":"Coachella","is_correct":false},{"id":"b","text":"Lollapalooza","is_correct":true},{"id":"c","text":"Bonnaroo","is_correct":false},{"id":"d","text":"Governors Ball","is_correct":false}],"explanation":"He headlined Lollapalooza Chicago in 2019, a first for a Latin act at a major US festival."},{"id":"q5","question":"Which Cardi B number-one single features J Balvin and Bad Bunny?","options":[{"id":"a","text":"Bodak Yellow","is_correct":false},{"id":"b","text":"WAP","is_correct":false},{"id":"c","text":"I Like It","is_correct":true},{"id":"d","text":"Up","is_correct":false}],"explanation":"I Like It (2018) topped the Billboard Hot 100 with J Balvin and Bad Bunny as guests."},{"id":"q6","question":"What is the title of J Balvin''s joint album with Bad Bunny?","options":[{"id":"a","text":"Oasis","is_correct":true},{"id":"b","text":"La Familia","is_correct":false},{"id":"c","text":"Los Dioses","is_correct":false},{"id":"d","text":"Colores","is_correct":false}],"explanation":"Oasis (2019) is the collaborative album; La Familia and Colores are J Balvin solo records."},{"id":"q7","question":"Who duets with J Balvin on the 2018 hit «X (Equis)»?","options":[{"id":"a","text":"Daddy Yankee","is_correct":false},{"id":"b","text":"Nicky Jam","is_correct":true},{"id":"c","text":"Ozuna","is_correct":false},{"id":"d","text":"Maluma","is_correct":false}],"explanation":"X pairs J Balvin with Nicky Jam — a nod to their 90s dancehall influence."},{"id":"q8","question":"Which album won J Balvin the 2018 Latin Grammy for Best Urban Music Album?","options":[{"id":"a","text":"Energía","is_correct":false},{"id":"b","text":"Colores","is_correct":false},{"id":"c","text":"Jose","is_correct":false},{"id":"d","text":"Vibras","is_correct":true}],"explanation":"Vibras took the award in 2018; Energía had already won the same category in 2016."}]'::jsonb,
