insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-rosalia-trivia',
  'Rosalía Trivia: Albums and Sound',
  'Flamenco, reggaetón and avant-pop: eight questions on the albums and collaborations that made Rosalía Spain''s most adventurous star.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"Which region of Spain is Rosalía from?","options":[{"id":"a","text":"Andalusia","is_correct":false},{"id":"b","text":"Galicia","is_correct":false},{"id":"c","text":"Catalonia","is_correct":true},{"id":"d","text":"Madrid","is_correct":false}],"explanation":"She was born in Sant Cugat del Vallès and grew up in Sant Esteve Sesrovires, near Barcelona."},{"id":"q2","question":"What was Rosalía''s debut album?","options":[{"id":"a","text":"El Mal Querer","is_correct":false},{"id":"b","text":"Los Ángeles","is_correct":true},{"id":"c","text":"Motomami","is_correct":false},{"id":"d","text":"Lux","is_correct":false}],"explanation":"Los Ángeles (2017), recorded with Raül Refree, was a set of flamenco standards — El Mal Querer came a year later."},{"id":"q3","question":"El Mal Querer is loosely based on which medieval text?","options":[{"id":"a","text":"La Celestina","is_correct":false},{"id":"b","text":"El Cantar de Mio Cid","is_correct":false},{"id":"c","text":"Libro de Buen Amor","is_correct":false},{"id":"d","text":"Flamenca","is_correct":true}],"explanation":"Each track works as a ''chapter'' of Flamenca, a 13th-century Occitan romance about an imprisoned woman."},{"id":"q4","question":"Who duets with Rosalía on «Con Altura»?","options":[{"id":"a","text":"J Balvin","is_correct":true},{"id":"b","text":"Bad Bunny","is_correct":false},{"id":"c","text":"Ozuna","is_correct":false},{"id":"d","text":"Maluma","is_correct":false}],"explanation":"Con Altura (2019) pairs Rosalía with J Balvin and producer El Guincho."},{"id":"q5","question":"In which year did she release Motomami?","options":[{"id":"a","text":"2019","is_correct":false},{"id":"b","text":"2020","is_correct":false},{"id":"c","text":"2022","is_correct":true},{"id":"d","text":"2024","is_correct":false}],"explanation":"Motomami came out in March 2022 and opened with Saoko."},{"id":"q6","question":"How many times has Rosalía won the Latin Grammy for Album of the Year?","options":[{"id":"a","text":"None","is_correct":false},{"id":"b","text":"Once","is_correct":false},{"id":"c","text":"Twice","is_correct":true},{"id":"d","text":"Three times","is_correct":false}],"explanation":"El Mal Querer won in 2019 and Motomami in 2022 — she became the first woman to take the prize twice."},{"id":"q7","question":"Which artist joins her on «La Noche de Anoche»?","options":[{"id":"a","text":"The Weeknd","is_correct":false},{"id":"b","text":"Bad Bunny","is_correct":true},{"id":"c","text":"Rauw Alejandro","is_correct":false},{"id":"d","text":"J Balvin","is_correct":false}],"explanation":"La Noche de Anoche (2021) is her duet with Bad Bunny; The Weeknd sings on La Fama instead."},{"id":"q8","question":"Which traditional Spanish genre does she fuse with urban pop?","options":[{"id":"a","text":"Flamenco","is_correct":true},{"id":"b","text":"Tango","is_correct":false},{"id":"c","text":"Zarzuela","is_correct":false},{"id":"d","text":"Copla","is_correct":false}],"explanation":"She studied flamenco for years in Barcelona — El Mal Querer even began as her conservatory thesis."}]'::jsonb,
  null,
  array['rosalia', 'spanish-pop', 'flamenco', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
