d":"a","text":"2020","is_correct":false},{"id":"b","text":"2021","is_correct":false},{"id":"c","text":"2022","is_correct":true},{"id":"d","text":"2023","is_correct":false}],"explanation":"Motomami salió en marzo de 2022 y abre con Saoko."},{"id":"q7","question":"¿Qué género tradicional español mezcla con el pop urbano?","options":[{"id":"a","text":"El tango","is_correct":false},{"id":"b","text":"La zarzuela","is_correct":false},{"id":"c","text":"La copla","is_correct":false},{"id":"d","text":"El flamenco","is_correct":true}],"explanation":"Estudió flamenco durante años en Barcelona; El Mal Querer nació como su tesis del conservatorio."},{"id":"q8","question":"¿Con qué artista une fuerzas en «La Noche de Anoche»?","options":[{"id":"a","text":"Bad Bunny","is_correct":true},{"id":"b","text":"The Weeknd","is_correct":false},{"id":"c","text":"Rauw Alejandro","is_correct":false},{"id":"d","text":"J Balvin","is_correct":false}],"explanation":"La Noche de Anoche (2021) es su dueto con Bad Bunny; con The Weeknd grabó La Fama."}]'::jsonb,
